function hex(h) {
  const n = parseInt(h.slice(1), 16);
  return { r: ((n >> 16) & 255) / 255, g: ((n >> 8) & 255) / 255, b: (n & 255) / 255 };
}

async function main() {
  await figma.loadFontAsync({ family: "Inter", style: "Regular" });
  await figma.loadFontAsync({ family: "Inter", style: "Bold" });
  let serifOK = false;
  try {
    await figma.loadFontAsync({ family: "Cormorant Garamond", style: "Medium" });
    await figma.loadFontAsync({ family: "Cormorant Garamond", style: "SemiBold" });
    serifOK = true;
  } catch (e) { serifOK = false; }
  const page = figma.currentPage;
  const frames = [];
  const COLS = 4, GX = 90, GY = 90;
  SCREENS.forEach((s, i) => {
    const frame = figma.createFrame();
    frame.name = s.name;
    frame.resize(s.width, s.height);
    frame.x = (i % COLS) * (s.width + GX);
    frame.y = Math.floor(i / COLS) * (860 + GY);
    frame.fills = [{ type: "SOLID", color: hex("#FFFFFF") }];
    frame.strokes = [{ type: "SOLID", color: hex("#BDBDBD") }];
    for (const bx of s.boxes) {
      if (bx.kind === "rect" || bx.kind === "photo") {
        const r = figma.createRectangle();
        r.x = bx.x; r.y = bx.y; r.resize(bx.w, bx.h);
        r.cornerRadius = bx.radius || 0;
        // Photo boxes arrive as navy panels in Figma; drop the real
        // photo in from the 05-hifi/img folder (or use the SVGs).
        r.fills = [{ type: "SOLID", color: hex(bx.kind === "photo" ? "#0F1F38" : bx.fill) }];
        if (bx.opacity != null) r.opacity = bx.opacity;
        if (bx.stroke) r.strokes = [{ type: "SOLID", color: hex(bx.stroke) }];
        frame.appendChild(r);
      } else if (bx.kind === "circle") {
        const e = figma.createEllipse();
        e.x = bx.cx - bx.r; e.y = bx.cy - bx.r; e.resize(bx.r * 2, bx.r * 2);
        e.fills = [{ type: "SOLID", color: hex(bx.fill) }];
        if (bx.stroke) e.strokes = [{ type: "SOLID", color: hex(bx.stroke) }];
        frame.appendChild(e);
      } else if (bx.kind === "text") {
        const t = figma.createText();
        if (bx.font === "serif" && serifOK) {
          t.fontName = { family: "Cormorant Garamond", style: bx.bold ? "SemiBold" : "Medium" };
        } else {
          t.fontName = { family: "Inter", style: bx.bold ? "Bold" : "Regular" };
        }
        t.characters = bx.text;
        t.fontSize = bx.size;
        t.fills = [{ type: "SOLID", color: hex(bx.color) }];
        t.x = bx.x; t.y = bx.y;
        if (bx.align === "center") { t.textAlignHorizontal = "CENTER"; t.resize(bx.w, bx.h); }
        if (bx.align === "right") { t.textAlignHorizontal = "RIGHT"; t.resize(bx.w, bx.h); }
        frame.appendChild(t);
      }
    }
    page.appendChild(frame);
    frames.push(frame);
  });
  figma.currentPage.selection = frames;
  figma.viewport.scrollAndZoomIntoView(frames);
  figma.closePlugin("Drew " + frames.length + " AlumniUp wireframe screens.");
}
main();
